using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in appsettings.json or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the search tool to find information about a topic, " +
    "use the note tool to record key findings, then provide a final summary of your notes.");

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ModelOptions = chatOptions,
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly: \"{topic}\". " +
        "Search for relevant information, take notes on key findings, " +
        "then retrieve your notes and provide a comprehensive summary."),
};

await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
{
    if (!string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Tool Definitions ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information about a query. Returns search result snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing, Google, etc.) in production.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        return $"""
            Search results for "{query}":
            1. Overview: {query} is a widely discussed topic with recent developments in 2025-2026.
            2. Key finding: Experts highlight that {query} has significant implications for technology and society.
            3. Recent news: New research papers and industry reports published in 2026 provide updated perspectives on {query}.
            4. Analysis: Multiple sources indicate growing interest and investment in {query} across sectors.
            """;
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note recorded ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken during this research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return "Your research notes:\n" +
            string.Join("\n", _notes.Select((n, i) => $"  {i + 1}. {n}"));
    }
}

